/** 벤더 예약 경계(초) — 분이 5의 배수이고 초가 00 인 시각만 큐에 들어간다 */
export const SCHEDULE_SLOT_SECONDS = 300;

/** 직전 경계로 내린다. 기한 알림은 늦으면 안 되므로 올리지 않는다. */
export function floorToSlot(t: LocalDateTime): LocalDateTime {
  const sec = toEpochSeconds(t);
  return fromEpochSeconds(sec - (sec % SCHEDULE_SLOT_SECONDS));
}

